static inline int atomic_read(const atomic_t *v) /* <=== atomic_read */ 
{
	return READ_ONCE((v)->counter);
}

static inline int atomic_set(atomic_t *v, int i) /* <=== atomic_set */ 
{
	unsigned long flags;

	__global_lock1(flags);
	fence();
	v->counter = i;
	__global_unlock1(flags);
	return i;
}

static inline void af_alg_init_completion(struct af_alg_completion *completion) /* <=== af_alg_init_completion */ 
{
	init_completion(&completion->completion);
}

void *sock_kmalloc(struct sock *sk, int size, gfp_t priority) /* <=== sock_kmalloc */ 
{
	if ((unsigned int)size <= sysctl_optmem_max &&
	    atomic_read(&sk->sk_omem_alloc) + size < sysctl_optmem_max) {
		void *mem;
		/* First do the add, to avoid the race if kmalloc
		 * might sleep.
		 */
		atomic_add(size, &sk->sk_omem_alloc);
		mem = kmalloc(size, priority);
		if (mem)
			return mem;
		atomic_sub(size, &sk->sk_omem_alloc);
	}
	return NULL;
}

static inline void INIT_LIST_HEAD(struct list_head *list) /* <=== INIT_LIST_HEAD */ 
{
	WRITE_ONCE(list->next, list);
	list->prev = list;
}

static inline unsigned int crypto_skcipher_reqsize(struct crypto_skcipher *tfm) /* <=== crypto_skcipher_reqsize */ 
{
	return tfm->reqsize;
}

void atomic_set(atomic_t *v, int i) /* <=== atomic_set */ 
{
	unsigned long flags;

	spin_lock_irqsave(ATOMIC_HASH(v), flags);
	v->counter = i;
	spin_unlock_irqrestore(ATOMIC_HASH(v), flags);
}

